230	/// LAZY indizierter Blick auf den statischen Teilbaum. „Interface, um die notwendigen statischen Eigenschaften
231	/// zur Kompilation aller Tier-Binaries indexiert mit einem Iterator zu durchlaufen" (User 2026-06-02). Hält NUR
232	/// die Ebenen-Metadaten + Divisoren; `operator[](i)` DEKODIERT den Index i mixed-radix on-demand zu genau EINER
233	/// BinarySpec (Ebene 0 = höchstwertig). Es wird NIE ein ∏-großes vector vorgehalten → der Build-Orchestrator
234	/// hält nur so viele Specs gleichzeitig wie zulässige DLL-Build-Prozesse.
235	class StaticBinaryView {
236	public:
237	    StaticBinaryView() = default;
238	    explicit StaticBinaryView(std::vector<AxisLevel> static_levels) : levels_{std::move(static_levels)} {
239	        size_ = levels_.empty() ? 0 : 1;
240	        for (auto const& l : levels_) size_ *= l.values.size(); // size_t-Kardinalität (∏ mod 2^64 bei Overflow)
241	        // Divisoren-Cache (most-significant = Ebene 0): div_[d] = ∏_{e>d} size_e
242	        div_.assign(levels_.size(), 1);
243	        for (std::size_t d = levels_.size(); d-- > 0;)
244	            div_[d] = (d + 1 < levels_.size()) ? div_[d + 1] * levels_[d + 1].values.size() : 1;
245	    }
246	    [[nodiscard]] std::size_t size() const noexcept { return size_; }
247	    [[nodiscard]] bool        empty() const noexcept { return size_ == 0; }
248	
249	    // ── D1 (L-SEL): Ebenen-Metadaten für die endliche BuildSelection (Coverage-Sampling) ──
250	    /// Zahl der statischen Ebenen (= Achsen der Binary-Identität).
251	    [[nodiscard]] std::size_t level_count() const noexcept { return levels_.size(); }
252	    /// Varianten-Zahl der Ebene d (0 wenn d außerhalb) — Eingabe für one_wise_cover_sample.
253	    [[nodiscard]] std::size_t level_size(std::size_t d) const noexcept {
254	        return d < levels_.size() ? levels_[d].values.size() : 0;
255	    }
256	    /// mixed-radix ENKODIERUNG (Inverse von operator[]): tuple[d] = Varianten-Index der Ebene d → flacher
257	    /// View-Index i (== Σ_d tuple[d]·div_[d]). Da div_ die Mixed-Radix-Stellenwerte hält, gilt
258	    /// (i / div_[d]) % level_size(d) == tuple[d] (für tuple[d] < level_size(d)) → operator[](flat_index(t)) trifft t.
259	    [[nodiscard]] std::size_t flat_index(std::span<const std::size_t> tuple) const noexcept {
260	        std::size_t i = 0;
261	        for (std::size_t d = 0; d < levels_.size() && d < tuple.size(); ++d) i += tuple[d] * div_[d];
262	        return i;
263	    }
264	
265	    /// On-demand: dekodiert Index i mixed-radix → EINE BinarySpec (materialisiert genau einen Pfad).
266	    [[nodiscard]] BinarySpec operator[](std::size_t i) const {
267	        BinarySpec s;
268	        s.index = i;
269	        std::string bin, pin;
270	        for (std::size_t d = 0; d < levels_.size(); ++d) {
271	            auto const& l = levels_[d];
272	            if (l.values.empty()) continue;
273	            std::size_t const k   = (i / div_[d]) % l.values.size();
274	            std::string       seg = l.axis;
275	            seg += '=';
276	            seg += l.values[k];
277	            if (!bin.empty()) bin += '/';
278	            bin += seg;
279	            if (l.values.size() == 1) {
280	                if (!pin.empty()) pin += '/';
281	                pin += seg;
282	            }
283	            s.axes.emplace_back(l.axis, l.values[k]);
284	        }
285	        s.binary_id        = std::move(bin);
286	        s.pinned_signature = std::move(pin);
287	        return s;
288	    }
289	
290	    /// LAZY input-iterator (materialisiert je Schritt genau EINE BinarySpec — by value).
291	    class iterator {
292	    public:
293	        using value_type        = BinarySpec;
294	        using difference_type   = std::ptrdiff_t;
295	        using iterator_category = std::input_iterator_tag;
296	        using pointer           = void;
297	        using reference         = BinarySpec;
298	        iterator()              = default;
299	        iterator(StaticBinaryView const* v, std::size_t i) : v_{v}, i_{i} {}
300	        [[nodiscard]] BinarySpec operator*() const { return (*v_)[i_]; }
301	        iterator&                operator++() {
302	            ++i_;
303	            return *this;
304	        }
305	        iterator operator++(int) {
306	            auto t = *this;
307	            ++i_;
308	            return t;
309	        }
310	        [[nodiscard]] bool operator==(iterator const& o) const { return i_ == o.i_; }
311	        [[nodiscard]] bool operator!=(iterator const& o) const { return i_ != o.i_; }
312	
313	    private:
314	        StaticBinaryView const* v_ = nullptr;
315	        std::size_t             i_ = 0;
316	    };
317	    [[nodiscard]] iterator begin() const { return {this, 0}; }
318	    [[nodiscard]] iterator end() const { return {this, size_}; }
319	
320	private:
321	    std::vector<AxisLevel>   levels_;
322	    std::vector<std::size_t> div_;
323	    std::size_t              size_ = 0;
324	};
