446	    /// KF-15: multimap<pinned signature, binary_id> — Paper-Wiedererkennung. ⚠️ O(∏) + ∏ Einträge: nur auf
447	    /// handhabbaren Bäumen aufrufen (die inverse Auswertung projiziert real GEMESSENE Blätter, Doc 26 §3).
448	    [[nodiscard]] std::multimap<std::string, std::string> pinned_signature_index() const {
449	        std::multimap<std::string, std::string> idx;
450	        for_each_binary(
451	            [&](std::string const& bin, std::string const& pin, TreeNode const&) { idx.emplace(pin, bin); });
452	        return idx;
453	    }
