455	    /// KF-16: LAZY indizierte Sicht auf den statischen Teilbaum (alle zu bauenden Tier-Binaries, geordnet).
456	    /// Hält NUR die Ebenen — operator[](i) dekodiert je Binary on-demand; der Build-Orchestrator materialisiert
457	    /// nur so viele Pfade gleichzeitig wie zulässige DLL-Build-Prozesse (User 2026-06-02).
458	    [[nodiscard]] StaticBinaryView static_binary_view() const { return StaticBinaryView{static_levels_}; }
459	
460	    // ── §2 per-node Observer-Statistics: SPARSE (nur GEMESSENE Binaries; BR-3) ──
461	    /// Setzt/aktualisiert die Mess-Auswertung EINES gemessenen Binary-Pfads (key = binary_id). Nur gemessene
462	    /// Pfade haben einen Eintrag — NIE alle ∏ (OOM-sicher).
463	    void set_node_value(std::string const& binary_id, NodeValue const& value) { value_map_[binary_id] = value; }
464	    [[nodiscard]] NodeValue node_value(std::string const& binary_id) const {
465	        auto it = value_map_.find(binary_id);
466	        return it == value_map_.end() ? NodeValue{} : it->second;
467	    }
468	    [[nodiscard]] std::size_t measured_node_count() const noexcept { return value_map_.size(); }
469	
470	    /// Zerlegt einen serialisierten Static-Pfad ("achse=wert/achse=wert/…") in (achse, wert)-Paare.
471	    [[nodiscard]] static std::vector<std::pair<std::string, std::string>> parse_axes(std::string const& path) {
472	        std::vector<std::pair<std::string, std::string>> out;
473	        std::size_t                                      i = 0;
474	        while (i < path.size()) {
475	            std::size_t slash = path.find('/', i);
476	            std::string seg   = path.substr(i, (slash == std::string::npos ? path.size() : slash) - i);
477	            std::size_t eq    = seg.find('=');
478	            if (eq != std::string::npos) out.emplace_back(seg.substr(0, eq), seg.substr(eq + 1));
479	            if (slash == std::string::npos) break;
480	            i = slash + 1;
481	        }
482	        return out;
483	    }
