58	/// make_union_source_gen — DIE EINE vereinigte SourceGenFn (S7a). `catalog_gen` = die Basis-320-SourceGenFn
59	/// (make_catalog_source_gen, source_catalog.hpp); `sota_by_view_id` = die SOTA-Reihen-Quellen, GEKEYT auf den
60	/// VIEW-binary_id ("sota_tier=…", build_sota_view_source_map). Ein binary_id, der in KEINER der beiden Quellen
61	/// liegt, liefert eine leere Quelle → der BuildOrchestrator markiert die DLL als nicht baubar (ehrlich sichtbar).
62	[[nodiscard]] inline ex::SourceGenFn make_union_source_gen(ex::SourceGenFn                    catalog_gen,
63	                                                           std::map<std::string, std::string> sota_by_view_id) {
64	    return [catalog_gen = std::move(catalog_gen),
65	            sota        = std::move(sota_by_view_id)](std::string const& binary_id) -> std::string {
66	        std::string src = catalog_gen ? catalog_gen(binary_id) : std::string{}; // (1) Basis-320 (disjunkt)
67	        if (!src.empty()) return src;
68	        auto it = sota.find(binary_id); // (2) SOTA-Reihen (disjunkt)
69	        return it == sota.end() ? std::string{} : it->second;
70	    };
71	}
