171	/// profile_axis_level — der Level-Index einer Achse im (tier-freien) statischen AxisLevel-Satz. -1 wenn unbekannt.
172	/// Single-Source: dieselbe Reihenfolge, die der StaticBinaryView verwendet (kCompositionAxisNames-Reihenfolge).
173	[[nodiscard]] inline std::size_t profile_axis_level(std::vector<ex::AxisLevel> const& static_basis_levels,
174	                                                    std::string const&                axis_name) {
175	    std::size_t d = 0;
176	    for (auto const& l : static_basis_levels) {
177	        if (!l.is_static) continue; // nur statische Ebenen tragen die binary_id
178	        if (l.axis == axis_name) return d;
179	        ++d;
180	    }
181	    return static_cast<std::size_t>(-1); // unbekannt → Caller verweigert (provenance-Marker)
182	}
