184	// ── Ein getaggter profil-getriebener Selektions-Pass (BuildSelection + die 2 Klassen-Tags series/sweep_axis). ──
185	struct ProfileTaggedSelection {
186	    ex::BuildSelection selection;
187	    std::string        series     = "-"; // SOTA-Reihe (hier immer "-" — sota_series erst Inc5)
188	    std::string        sweep_axis = "-"; // gesweepte Achse oder "-" (Basis)
189	    std::string        label;
190	};
191	
192	/// profile_make_basis — BASIS-320: die ersten `cap` View-Indizes (voll-faktoriell, identisch zum heutigen
193	/// "index"/make_basis-Modus). Tag series="-" sweep_axis="-". Reine explizite Index-Liste (kein Ad-hoc).
194	[[nodiscard]] inline ProfileTaggedSelection profile_make_basis(ex::StaticBinaryView const& view, std::size_t cap) {
195	    std::size_t const        n = (std::min)(cap, view.size());
196	    std::vector<std::size_t> ids;
197	    ids.reserve(n);
198	    for (std::size_t i = 0; i < n; ++i) ids.push_back(i);
199	    ProfileTaggedSelection ts;
200	    ts.selection  = ex::select_explicit(std::move(ids));
201	    ts.series     = "-";
202	    ts.sweep_axis = "-";
203	    ts.label      = "basis-320";
204	    return ts;
205	}
206	
207	/// profile_make_axis_sweep — PER-ACHSEN-SWEEP gegen die feste Baseline (alle Ebenen Index 0) variiert GENAU die
208	/// Achse `level_d` ueber ihre Ausprägungen (via StaticBinaryView::flat_index — Achsen-Austausch IM Praefixbaum).
209	/// Funktional identisch zu m3v2::make_axis_sweep, aber der level_d kommt aus profile_axis_level (PROFIL-getrieben).
210	[[nodiscard]] inline ProfileTaggedSelection profile_make_axis_sweep(ex::StaticBinaryView const& view,
211	                                                                    std::size_t level_d, std::string const& axis_name,
212	                                                                    std::size_t cap) {
213	    ProfileTaggedSelection ts;
214	    ts.series     = "-";
215	    ts.sweep_axis = axis_name;
216	    ts.label      = "sweep:" + axis_name;
217	    if (level_d == static_cast<std::size_t>(-1) || level_d >= view.level_count()) {
218	        ts.selection.provenance = "axis_sweep-REFUSED-no-such-level";
219	        return ts;
220	    }
221	    std::size_t const        k = view.level_size(level_d);
222	    std::vector<std::size_t> tuple(view.level_count(), 0); // Baseline: alle Achsen Index 0 (FESTE Baseline-Tier)
223	    std::size_t const        n = (std::min)(cap, k);
224	    std::vector<std::size_t> ids;
225	    ids.reserve(n);
226	    for (std::size_t v = 0; v < n; ++v) {
227	        tuple[level_d] = v;                    // NUR die eine Achse austauschen
228	        ids.push_back(view.flat_index(tuple)); // Praefixbaum-Index (mixed-radix), kein Flach-Tupel
229	    }
230	    ts.selection            = ex::select_explicit(std::move(ids));
231	    ts.selection.provenance = "axis_sweep:" + axis_name;
232	    return ts;
233	}
234	
235	/// profile_select — die EINE profil-getriebene Selektions-Auswahl, gesteuert ueber `series_axis_or_empty`:
236	///   • ""  / "basis"        → BASIS-320 (profile_make_basis).
237	///   • "<achse>"            → PER-ACHSEN-SWEEP: matcht einen <axis_sweep axis="<achse>"> im Profil; der level_d
238	///                            wird ueber profile_axis_level aus den tier-freien Basis-Levels aufgeloest.
239	/// Verweigert (provenance-Marker) wenn die Achse NICHT als <axis_sweep> deklariert ist (= profil-getrieben:
240	/// nur deklarierte Sweeps sind waehlbar — die hartkodierte axis_to_level-Map ist ersetzt).
241	[[nodiscard]] inline ProfileTaggedSelection profile_select(cx::ThesisProfile const&          tp,
242	                                                           std::vector<ex::AxisLevel> const& static_basis_levels,
243	                                                           ex::StaticBinaryView const&       view,
244	                                                           std::string const& series_axis_or_empty, std::size_t cap) {
245	    if (series_axis_or_empty.empty() || series_axis_or_empty == "basis" || series_axis_or_empty == "index")
246	        return profile_make_basis(view, cap);
247	    // Per-Achsen-Sweep: die Achse MUSS als <axis_sweep> deklariert sein (profil-getriebene Whitelist).
248	    bool declared = false;
249	    for (auto const& sw : tp.axis_sweeps)
250	        if (sw.axis == series_axis_or_empty) {
251	            declared = true;
252	            break;
253	        }
254	    ProfileTaggedSelection ts;
255	    if (!declared) {
256	        ts.sweep_axis           = series_axis_or_empty;
257	        ts.label                = "sweep:" + series_axis_or_empty;
258	        ts.selection.provenance = "axis_sweep-REFUSED-not-declared-in-profile";
259	        return ts;
260	    }
261	    std::size_t const level_d = profile_axis_level(static_basis_levels, series_axis_or_empty);
262	    return profile_make_axis_sweep(view, level_d, series_axis_or_empty, cap);
263	}
